  -- ---- the menu of an empty slot -----------------------------------------------------------------------------------

  function F.OpenMenu(slot)
    local set, ty = F.Squad()
    if type(set) ~= "number" or not TP.Info() then
      return false
    end
    local plans = TP.Plans(set, ty)
    local rows = {}
    if not F.Closed(F.DOCK_MENU) and type(FuncCloseFormationMenu) == "function" then
      rows[#rows + 1] = {id = F.T_ADD_BANK, act = "bank"}
    end
    rows[#rows + 1] = {id = F.T_PLAN, act = "plan"}
    if plans[slot] ~= nil then
      rows[#rows + 1] = {id = F.T_UNPLAN, act = "unplan"}
    end
    local ids, en, new = {}, {}, {}
    for i, r in ipairs(rows) do
      ids[i], en[i], new[i] = r.id, 1, 0
    end
    F.rows, F.slot, F.choice = rows, slot, nil
    if type(SetSubMenuBusy) == "function" then
      SetSubMenuBusy(true)
    end
    TP.Snd(TP.SY_OK)
    -- one cursor owner: the popup's own row cursor; the formation's cursor (the slot's arrow, behind the popup) is
    -- hidden until the popup closes
    TP.M(TP.C.LAYER_VISIBLE, F.CURSOR, 0, false)
    MENU_DEF.OpenSubWindow("UTIL_TP_OnMenu", "", #rows, ids, F.SIZE[#rows] or 0, F.TITLE_SPRITE, en, 0, false, false, 0, 0, new)
    F.state = "menu_opening"
    TP.Log("menu: squad", set, ty, "slot", slot, #rows, "row(s)")
    return true
  end

  function F.OnMenu(a1)
    if F.state ~= "menu_opening" and F.state ~= "menu" then
      return
    end
    F.choice = type(a1) == "number" and a1 >= 0 and F.rows[a1 + 1] or nil
    if F.choice ~= nil then
      funcLuaCommand(F.C.CLOSE_OBJ, F.SUB_WINDOW)
    end
    F.state = "menu_closing"
  end

  function F.MenuDone()
    if type(SetSubMenuBusy) == "function" then
      SetSubMenuBusy(false)
    end
    local c = F.choice
    F.choice = nil
    F.state = nil
    if c == nil or c.act ~= "plan" then
      -- the picker hides it itself (and shows it again when it closes)
      TP.M(TP.C.LAYER_VISIBLE, F.CURSOR, 0, true)
    end
    if c == nil then
      return
    end
    local set, ty = F.Squad()
    if c.act == "bank" then
      funcLuaCommand(TP.C.PARAM_DEL, TP.KEY_BANK)
      funcLuaCommand(TP.C.PARAM_SET, TP.KEY_BANK, 0, set, 1)
      local okh, has = pcall(funcLuaCommand, TP.C.PARAM_HAS, TP.KEY_BANK)
      TP.Log("«Añadir del banco»: squad", set, "request stored", tostring(okh and has))
      pcall(FuncCloseFormationMenu)
    elseif c.act == "plan" then
      if not F.PickerOpen() then
        TP.Snd(TP.SY_ERROR)
      end
    elseif c.act == "unplan" then
      TP.SetPlan(set, ty, F.slot, 0)
      TP.Ghosts(set, ty, F.slot)
      TP.Snd(TP.SY_OK)
    end
  end

  -- ---- the picker: team emblem grid --------------------------------------------------------------------------------

  -- the black backdrop under the picker (the formation's own cmn02_01_blackbg, at the grids' priority - 1)
  function F.Backdrop(on)
    if on then
      local base = TP.M(F.C.GET_PRIO, TP.CARD, 0)
      F.prio = (type(base) == "number" and base or 400) + 40
      F.backdrop_was_open = TP.M(F.C.IS_OPEN_LAYER, F.BACKDROP, 0) == true
      if not F.backdrop_was_open then
        TP.M(F.C.OPEN_LAYER, F.BACKDROP, 0)
      end
      TP.M(TP.C.LAYER_VISIBLE, F.BACKDROP, 0, true)
      TP.M(F.C.SET_PRIO, F.BACKDROP, 0, F.prio - 1)
      TP.M(TP.C.LAYER_VISIBLE, F.CURSOR, 0, false)
    elseif F.backdrop_was_open then
      TP.M(TP.C.LAYER_VISIBLE, F.BACKDROP, 0, false)
    else
      TP.M(F.C.CLOSE_LAYER, F.BACKDROP)
    end
  end

  -- the framework's team emblem grid on Utilities' layers util_tp_emblem / util_tp_label (nil: not there)
  function F.TeamsGrid()
    if F.eg == nil then
      if type(VRFW_EmblemGrid) ~= "table" or type(VRFW_EmblemGrid.New) ~= "function" then
        TP.Log("team grid: VRFW_EmblemGrid missing (VR-Framework too old)")
        return nil
      end
      local cols, rows, px, py, cx, cy = TP.Cmd(TP.C.PICK_TEAM_GRID)
      if type(cols) ~= "number" then
        cols, rows, px, py, cx, cy = 8, 3, 210, 236, 960, 520
      end
      F.eg = VRFW_EmblemGrid.New({tile = F.EMBLEM_LAYER, label = F.LABEL_LAYER, cols = cols, rows = rows, px = px,
                                  py = py, cx = cx, cy = cy, prio = F.prio, log = TP.Log})
    end
    F.eg.prio = F.prio
    if not F.eg.ok then
      TP.Log("team grid: layer util_tp_emblem not in soccer_formation_menu: install the mod")
      return nil
    end
    return F.eg
  end

  function F.PickerOpen()
    local okL, lang = pcall(funcLuaCommand, F.C.LANG)
    local pages = TP.Cmd(TP.C.PICK_OPEN, okL and lang or -1)
    if type(pages) ~= "number" or pages < 1 then
      TP.Log("picker: no catalogue")
      return false
    end
    F.Input(false)
    F.Backdrop(true)
    F.focus = 1
    F.built, F.opened = F.built or {}, F.opened or {}
    TP.Log("picker opened:", pages, "season(s)")
    return F.ListOpen()
  end

  -- ---- the season list ---------------------------------------------------------------------------------------------

  -- the list's layout (CMND_UTIL_TP_PICK_LIST, [team_planner.list])
  F.LIST_DEFAULT = {cols = 5, rows = 3, pitch_x = 180, pitch_y = 215, scale = 1.0, cx = 500, cy = 610, ox = 0, oy = 0,
                    ghost_alpha = 0.45, tab_x = 110, tab_y = 230, tab_pitch = 78, tab_scale = 1.0, back_x = 0,
                    back_y = 0, back_sx = 0.54, back_sy = 1.0}
  function F.ListLayout()
    local t = TP.Cmd(TP.C.PICK_LIST)
    if type(t) ~= "table" then
      t = {}
    end
    local v, missing = {}, {}
    for k, d in pairs(F.LIST_DEFAULT) do
      local x = t[k]
      if type(x) == "number" then
        v[k] = x
      else
        v[k] = d
        missing[#missing + 1] = k
      end
    end
    if #missing > 0 and not F.list_warned then
      F.list_warned = true
      table.sort(missing)
      TP.Log("season list: [team_planner.list] keys not answered, defaults used: " .. table.concat(missing, ", "))
    end
    return {cols = v.cols, rows = v.rows, px = v.pitch_x, py = v.pitch_y, scale = v.scale, cx = v.cx, cy = v.cy, ox = v.ox,
            oy = v.oy, alpha = v.ghost_alpha, tab_x = v.tab_x, tab_y = v.tab_y, tab_pitch = v.tab_pitch,
            tab_scale = v.tab_scale, back_x = v.back_x, back_y = v.back_y, back_sx = v.back_sx, back_sy = v.back_sy}
  end

  -- the dark panel behind the list: the backdrop layer moved / scaled over the list's side (nil = back to whole)
  function F.Panel(Lo)
    if Lo == nil then
      TP.M(F.C.LOCAL_POS, F.BACKDROP, 0, 0, 0, 0)
      TP.M(F.C.LOCAL_SCALE, F.BACKDROP, 1, 1, 1, 0)
      return
    end
    TP.M(F.C.LOCAL_POS, F.BACKDROP, Lo.back_x, -Lo.back_y, 0, 0)
    TP.M(F.C.LOCAL_SCALE, F.BACKDROP, Lo.back_sx, Lo.back_sy, 1, 0)
  end

  function F.ListOpen()
    local L = F.CARD_LAYER
    local have = TP.M(F.C.LAYER_NUM, L)
    if type(have) ~= "number" or have < 1 then
      TP.Log("list: layer util_tp_card not in soccer_formation_menu (" .. tostring(have) .. "): install the mod")
      F.Finish()
      return false
    end
    F.list = F.ListLayout()
    F.Panel(F.list)
    local tabs = TP.Cmd(TP.C.PICK_TABS)
    F.tabs = type(tabs) == "table" and tabs or {}
    F.tab_open = F.tab_open or {}
    return F.SeasonShow(0, 0)
  end

  -- the season tab `dir` away (or tab `at`, 1-based) as the list
  function F.SeasonShow(dir, at)
    local page, name, on, n, pages = TP.Cmd(TP.C.PICK_SEASON, dir or 0, at or 0)
    if type(page) ~= "number" or type(n) ~= "number" then
      TP.Snd(TP.SY_ERROR)
      F.Finish()
      return false
    end
    local roster = TP.Cmd(TP.C.PICK_ROSTER)
    if F.grid ~= nil then
      F.GridClose(false)
    end
    local Lo, have = F.list, TP.M(F.C.LAYER_NUM, F.CARD_LAYER)
    local per = math.max(1, math.min(Lo.cols * Lo.rows, type(have) == "number" and have or 1))
    local G = {n = n, owned = on or 0, team = tostring(name), cols = Lo.cols, rows = math.ceil(per / Lo.cols), per = per,
               px = Lo.px, py = Lo.py, scale = Lo.scale, cx = Lo.cx, cy = Lo.cy, ox = Lo.ox, oy = Lo.oy, alpha = Lo.alpha,
               players = {}, sel = 0, held = {}, drawn = {}, shown = {}, wait = {},
               season = {page = page, pages = pages or 1}}
    for j = 1, n do
      local e = type(roster) == "table" and roster[j] or nil
      if type(e) == "table" then
        G.players[j] = {param = type(e[1]) == "number" and e[1] or 0, owned = e[2] == true,
                        rarity = type(e[3]) == "number" and e[3] or 4, name = tostring(e[4] or "")}
      else
        G.players[j] = {param = 0, owned = false, rarity = 4, name = ""}
      end
    end
    G.prio = F.prio or 440
    F.grid = G
    F.state = "grid"
    F.KeysReset()
    F.Tabs(page)
    F.GridDraw()
    TP.Log(string.format("season list: tab %d/%d %s, %d character(s), %d owned, %d a page", page, pages or 0, G.team, n,
      G.owned, per))
    return true
  end

  -- the centre of season tab i (1-based) in screen px (y down)
  function F.TabCentre(i)
    local Lo = F.list
    return Lo.tab_x + (i - 1) * Lo.tab_pitch, Lo.tab_y
  end

  -- the tab bar: one bank tab a season, the current one in its focused look (cur = nil hides the bar)
  function F.Tabs(cur)
    local L = F.TAB_LAYER
    local have = TP.M(F.C.LAYER_NUM, L)
    have = type(have) == "number" and have or 0
    local mods = {}
    if cur ~= nil and type(VRFW_BankTabs) == "table" and type(VRFW_BankTabs.List) == "function" then
      local ok, l = pcall(VRFW_BankTabs.List)
      mods = (ok and type(l) == "table") and l or {}
    end
    for k = 0, have - 1 do
      local t = cur ~= nil and F.tabs[k + 1] or nil
      if t == nil then
        if F.tab_open[k] then
          TP.M(TP.C.LAYER_VISIBLE, L, k, false)
        end
      else
        if not F.tab_open[k] then
          TP.M(F.C.OPEN_LAYER, L, k)
          F.tab_open[k] = true
        end
        local atlas, on, off = t[3] or 0, t[4] or 0, t[5] or 0
        if atlas == 0 then            -- a mod's series: the framework's bank tab of that series
          for _, m in ipairs(mods) do
            if m.series == t[1] then
              atlas, on, off = m.atlas or 0, m.icon or 0, m.off or 0
              break
            end
          end
        end
        if atlas ~= 0 then
          TP.M(F.SET_SPRITE, L, atlas, on, F.TAB_DMY_ON, 0, k)
          TP.M(F.SET_SPRITE, L, atlas, off, F.TAB_DMY_OFF, 0, k)
        end
        TP.M(F.MESH_VISIBLE, L, F.TAB_ICON_BASE, true, k)
        local x, y = F.TabCentre(k + 1)
        local sc = F.list.tab_scale
        TP.M(F.C.LOCAL_SCALE, L, sc, sc, 1, k)
        TP.M(F.C.LOCAL_POS, L, x, -y, 0, k)
        TP.M(F.C.SET_PRIO, L, k, (F.prio or 440) + 2)
        TP.M(F.C.ANIME, L, k, F.FOCUS, (k + 1) == cur and 0 or 2, F.BUTTON)
        TP.M(TP.C.LAYER_VISIBLE, L, k, true)
      end
    end
  end

  -- the season tab under the pointer (1-based; nil = none)
  function F.TabHit(x, y)
    if type(x) ~= "number" or type(y) ~= "number" or F.list == nil then
      return nil
    end
    for i = 1, #F.tabs do
      local cx, cy = F.TabCentre(i)
      if math.abs(x - cx) <= F.list.tab_pitch / 2 and math.abs(y - cy) <= 40 then
        return i
      end
    end
    return nil
  end

  function F.TeamItem(i)
    local tname, own, n, emblem = TP.Cmd(TP.C.PICK_ITEM, i)
    if type(tname) ~= "string" then
      return {name = "?", count = "", emblem = 0}
    end
    own, n = type(own) == "number" and own or 0, type(n) == "number" and n or 0
    return {name = tname, count = string.format("%d/%d", own, n), emblem = type(emblem) == "number" and emblem or 0,
            full = n > 0 and own == n}
  end

  function F.TeamsHeader()
    local eg, s = F.eg, F.series or {}
    local head = F.Fmt(F.T_TAB, "‹ %s  %d/%d ›", tostring(s.name or ""), s.on or 0, s.n or 0)
    local it = eg and eg.items[eg:Sel()] or nil
    if it ~= nil then
      head = head .. "   ·   " .. it.name .. "  " .. it.count
    end
    local page, pages = eg:Page()
    if pages > 1 then
      head = head .. string.format("  (%d/%d)", page + 1, pages)
    end
    F.Header(head .. "   " .. TP.Text(F.T_TEAMS_HINT, ""))
  end

  -- the page `dir` away (0 = the same one), its teams on the grid
  function F.ShowTab(dir)
    local page, name, on, n, rows = TP.Cmd(TP.C.PICK_TAB, dir)
    local eg = F.TeamsGrid()
    if type(page) ~= "number" or type(rows) ~= "number" or eg == nil then
      TP.Snd(TP.SY_ERROR)
      F.Finish()
      return false
    end
    F.series = {name = tostring(name), on = on or 0, n = n or 0}
    local items = {}
    for i = 1, rows do
      items[i] = F.TeamItem(i)
    end
    F.state = "teams"
    eg:Open(items, F.focus or 1)
    F.TeamsHeader()
    return true
  end

  function F.TeamsStep()
    local eg = F.eg
    local before = eg:Sel()
    local ev = eg:Step()
    if eg:Sel() ~= before then
      F.TeamsHeader()
    end
    if ev == nil then
      return
    end
    if ev.act == "back" then
      F.Finish()
    elseif ev.act == "series" then
      TP.Snd(TP.SY_MOVE)
      F.focus = 1
      F.ShowTab(ev.dir)
    elseif ev.act == "decide" then
      F.team, F.focus = ev.index, ev.index
      eg:Hide()
      if not F.GridOpen(ev.index) then
        TP.Snd(TP.SY_ERROR)
        F.ShowTab(0)
      end
    end
  end

  -- close everything; `planned` = a card was chosen
  function F.Finish(planned)
    if F.eg ~= nil then
      F.eg:Close()
    end
    if F.grid ~= nil then
      F.GridClose(false)
    end
    F.grid = nil
    if F.list ~= nil then
      F.Tabs(nil)
      F.Panel(nil)
      F.list = nil
    end
    F.Backdrop(false)
    F.HeaderBack()
    F.state = nil
    F.Input(true)
    TP.M(TP.C.LAYER_VISIBLE, F.CURSOR, 0, true)
    if not planned then
      TP.Snd(TP.SY_BACK)
    end
    TP.Log("picker closed")
  end

  -- ---- the picker: card grid ---------------------------------------------------------------------------------------

  function F.GridOpen(i)
    local L = F.CARD_LAYER
    local have = TP.M(F.C.LAYER_NUM, L)
    if type(have) ~= "number" or have < 1 then
      TP.Log("grid: layer util_tp_card not in soccer_formation_menu (" .. tostring(have) .. "): install the mod")
      return false
    end
    local n, owned, tname = TP.Cmd(TP.C.PICK_TEAM, i)
    if type(n) ~= "number" or n < 1 then
      return false
    end
    local cols, rows, px, py, scale, cx, cy, ox, oy, alpha = TP.Cmd(TP.C.PICK_GRID)
    if type(cols) ~= "number" then
      cols, rows, px, py, scale, cx, cy, ox, oy, alpha = 8, 2, 215, 260, 1.35, 960, 560, 0, 0, 0.45
    end
    local per = math.max(1, math.min(cols * rows, have))
    local G = {n = n, owned = owned or 0, team = tostring(tname), cols = cols, rows = math.ceil(per / cols), per = per,
               px = px, py = py, scale = scale, cx = cx, cy = cy, ox = ox, oy = oy, alpha = alpha,
               players = {}, sel = 0, held = {}, drawn = {}, shown = {}, wait = {}}
    for j = 1, n do
      local param, own, rarity, name = TP.Cmd(TP.C.PICK_PLAYER, j)
      G.players[j] = {param = type(param) == "number" and param or 0, owned = own == true,
                      rarity = type(rarity) == "number" and rarity or 4, name = tostring(name or "")}
    end
    G.prio = F.prio or 440
    F.grid = G
    F.state = "grid"
    F.KeysReset()
    F.GridDraw()
    TP.Log(string.format("grid opened: %s, %d character(s), %d owned, %d a page", G.team, n, G.owned, per))
    return true
  end

  function F.GridClose(back)
    local G = F.grid
    if G ~= nil then
      for k = 0, G.per - 1 do
        if F.opened[k] then
          TP.M(TP.C.LAYER_VISIBLE, F.CARD_LAYER, k, false)
        end
      end
    end
    F.grid = nil
    if back then
      F.focus = F.team or 1
      F.ShowTab(0)
    end
  end

  -- the centre of cell k of the page in layer space (from the screen's top left, y up); the rows the page uses are
  -- centred on the grid's centre
  function F.Cell(k)
    local G = F.grid
    local c, r = k % G.cols, math.floor(k / G.cols)
    local page = math.floor(G.sel / G.per)
    local used = math.max(1, math.min(G.rows, math.ceil(math.min(G.per, G.n - page * G.per) / G.cols)))
    local x = G.cx + (c - (G.cols - 1) / 2) * G.px
    local y = G.cy + (r - (used - 1) / 2) * G.py
    return x, -y
  end

  -- tile k shows character d (1-based; nil = hidden)
  function F.Tile(k, d)
    local G, L = F.grid, F.CARD_LAYER
    local p = d and G.players[d] or nil
    if p == nil or p.param == 0 then
      if F.opened[k] then
        TP.M(TP.C.LAYER_VISIBLE, L, k, false)
      end
      G.drawn[k], G.shown[k], G.wait[k] = nil, nil, nil
      return
    end
    if not F.opened[k] then
      TP.M(F.C.OPEN_LAYER, L, k)
      F.opened[k] = F.frame
    end
    if G.drawn[k] ~= p.param then
      G.drawn[k], G.shown[k], G.wait[k] = nil, nil, nil
      G.want = G.want or {}
      G.want[k] = d
    end
    local focus = (d - 1) == G.sel
    local s = G.scale * (focus and F.FOCUS_SCALE or 1)
    local x, y = F.Cell(k)
    TP.M(F.C.LOCAL_SCALE, L, s, s, 1, k)
    TP.M(F.C.LOCAL_POS, L, x - G.ox * s, y + G.oy * s, 0, k)
    TP.M(F.C.SET_PRIO, L, k, G.prio + (focus and 1 or 0))
    TP.M(F.C.ANIME, L, k, F.FOCUS, focus and 0 or 2, F.BUTTON)
    if G.shown[k] then
      TP.Alpha(L, k, p.owned and 1 or G.alpha)
    end
  end

  -- per frame: a tile's card is drawn once its instance is built (or BUILD_WAIT frames after it was opened) and shown
  -- once its textures are loaded (or LOAD_WAIT frames later)
  function F.CardStep()
    local G, L = F.grid, F.CARD_LAYER
    for k, d in pairs(G.want or {}) do
      if F.built[k] ~= nil or F.frame - (F.opened[k] or F.frame) >= F.BUILD_WAIT then
        local p = G.players[d]
        G.want[k] = nil
        if p ~= nil then
          TP.M(TP.C.LAYER_VISIBLE, L, k, false)
          TP.M(TP.C.CARD_BY_PARAM, L, k, p.param, false, false, 0, 0, 1, false, false, p.rarity, 0, false, false, 0,
            false, false, false)
          G.drawn[k], G.wait[k] = p.param, F.LOAD_WAIT
        end
      end
    end
    for k, left in pairs(G.wait) do
      local loading = TP.M(F.C.LOADING, L, k) == true
      if not loading or left <= 0 then
        G.wait[k], G.shown[k] = nil, true
        TP.M(TP.C.LAYER_VISIBLE, L, k, true)
        local d = math.floor(G.sel / G.per) * G.per + k + 1
        local p = G.players[d]
        TP.Alpha(L, k, (p ~= nil and p.owned) and 1 or G.alpha)
      else
        G.wait[k] = left - 1
      end
    end
  end

  function F.GridDraw()
    local G = F.grid
    local page = math.floor(G.sel / G.per)
    for k = 0, G.per - 1 do
      local d = page * G.per + k + 1
      F.Tile(k, d <= G.n and d or nil)
    end
    local p = G.players[G.sel + 1]
    local who = ""
    if p ~= nil then
      who = p.name .. "  " .. (p.owned and TP.Text(F.T_OWNED, "(owned)") or TP.Text(F.T_MISSING, "(not owned)"))
    end
    local pages = math.ceil(G.n / G.per)
    local head = F.Fmt(F.T_INFO, "%s  %d/%d  -  %s", G.team, G.owned, G.n, who)
    if pages > 1 then
      head = head .. string.format("  (%d/%d)", page + 1, pages)
    end
    F.Header(head)
  end

  function F.In(input)
    for _, c in ipairs(F.CTRLS) do
      local ok, r = pcall(funcLuaCommand, F.C.CHECK_INPUT, c, input)
      if ok and r == true then
        return true
      end
    end
    return false
  end

  function F.KeysReset()
    local G = F.grid
    for name, input in pairs(F.KEYS) do
      G.held[name] = F.In(input) and 1000 or 0
    end
    G.ptr_x, G.ptr_y = TP.M(F.C.POINTER)
  end

  function F.Pressed(name, repeats)
    local G = F.grid
    local now = F.In(F.KEYS[name])
    local h = G.held[name] or 0
    if not now then
      G.held[name] = 0
      return false
    end
    G.held[name] = h + 1
    if h == 0 then
      return true
    end
    return repeats and h >= F.REPEAT_FIRST and (h - F.REPEAT_FIRST) % F.REPEAT_EVERY == 0
  end

  function F.GridMove(to)
    local G = F.grid
    if to < 0 or to >= G.n or to == G.sel then
      return
    end
    G.sel = to
    TP.Snd(TP.SY_MOVE)
    F.GridDraw()
  end

  function F.GridHit(x, y)
    local G = F.grid
    if type(x) ~= "number" or type(y) ~= "number" then
      return nil
    end
    local page = math.floor(G.sel / G.per)
    for k = 0, G.per - 1 do
      local d = page * G.per + k
      if d < G.n then
        local cx, cy = F.Cell(k)
        if math.abs(x - cx) <= G.px / 2 and math.abs(y + cy) <= G.py / 2 then
          return d
        end
      end
    end
    return nil
  end

  -- A on character j (0-based): the slot's plan
  function F.GridPick(j)
    local G = F.grid
    local p = G.players[j + 1]
    local set, ty = F.Squad()
    if p == nil or p.param == 0 or not TP.SetPlan(set, ty, F.slot, p.param) then
      TP.Snd(TP.SY_ERROR)
      return
    end
    TP.Snd(TP.SY_OK)
    TP.Log(string.format("planned: squad %s/%s slot %s = 0x%08X (%s, %s)", tostring(set), tostring(ty), tostring(F.slot),
      p.param, p.name, p.owned and "owned" or "not owned"))
    F.GridClose(false)
    F.Finish(true)
    TP.Ghosts(set, ty, F.slot)
  end

  function F.GridStep()
    local G = F.grid
    F.CardStep()
    local P = {}
    for _, k in ipairs({"back", "rclick", "click", "enter", "l1", "r1", "l2", "r2", "wup", "wdown"}) do
      P[k] = F.Pressed(k)
    end
    for _, k in ipairs({"left", "right", "up", "down"}) do
      P[k] = F.Pressed(k, true)
    end
    if P.back or P.rclick then
      if G.season ~= nil then
        F.Finish()
        return
      end
      TP.Snd(TP.SY_BACK)
      F.GridClose(true)
      return
    end
    if G.season ~= nil and (P.l2 or P.r2) and G.season.pages > 1 then
      TP.Snd(TP.SY_MOVE)
      F.SeasonShow(P.l2 and -1 or 1, 0)
      return
    end
    local x, y = TP.M(F.C.POINTER)
    local moved = TP.M(F.C.POINTER_MOVED) == true
    if type(x) == "number" and (moved or x ~= G.ptr_x or y ~= G.ptr_y) then
      G.ptr_x, G.ptr_y = x, y
      local d = F.GridHit(x, y)
      if d ~= nil then
        F.GridMove(d)
      end
    end
    if P.click and G.season ~= nil then
      local t = F.TabHit(x, y)
      if t ~= nil then
        if t ~= G.season.page then
          TP.Snd(TP.SY_MOVE)
          F.SeasonShow(0, t)
        end
        return
      end
    end
    if P.click then
      local d = F.GridHit(x, y)
      if d ~= nil then
        G.sel = d
        F.GridPick(d)
      end
      return
    end
    local c = G.cols
    local col = G.sel % c
    if P.left then
      F.GridMove(col > 0 and G.sel - 1 or math.min(G.sel + c - 1, G.n - 1))
    elseif P.right then
      F.GridMove((col < c - 1 and G.sel + 1 < G.n) and G.sel + 1 or G.sel - col)
    elseif P.up then
      F.GridMove(G.sel - c >= 0 and G.sel - c or G.sel)
    elseif P.down then
      F.GridMove(math.min(G.sel + c, G.n - 1))
    elseif P.l1 or P.wup then
      F.GridMove(math.max(G.sel - G.per, 0))
    elseif P.r1 or P.wdown then
      F.GridMove(math.min(G.sel + G.per, G.n - 1))
    elseif P.enter then
      F.GridPick(G.sel)
    end
  end

  -- per frame: the windows' open / close, the grid
  function F.Step()
    F.frame = F.frame + 1
    local st = F.state
    if st == "menu_opening" then
      local ok, open = pcall(funcLuaCommand, F.C.IS_OPEN, F.SUB_WINDOW, F.CURSOR)
      if ok and open == true then
        pcall(funcLuaCommand, F.C.SUB_OPEN_POS, 500, -260)
        F.state = "menu"
      end
    elseif st == "menu_closing" then
      if F.Closed(F.SUB_WINDOW) then
        F.MenuDone()
      end
    elseif st == "teams" and F.eg ~= nil then
      F.TeamsStep()
    elseif st == "grid" and F.grid ~= nil then
      F.GridStep()
    end
  end

  rawset(_ENV, "UTIL_TP_OnMenu", function(...) return F.OnMenu(...) end)

  -- ---- hooks -------------------------------------------------------------------------------------------------------

  TP.Wrap(STEM, "OnInit", function(orig)
    return function(...)
      TP.ghost, F.state, F.grid, F.built, F.opened = {}, nil, nil, {}, {}
      F.eg = nil                        -- a new menu: new layer instances
      F.tab_open, F.list, F.tabs = {}, nil, {}
      F.set, F.type = nil, 0
      local okA, hasA = pcall(funcLuaCommand, TP.C.PARAM_HAS, F.PARAM_DOCK)
      if okA and hasA then
        F.set = funcLuaCommand(TP.C.PARAM_GET, F.PARAM_DOCK)
      end
      local okB, hasB = pcall(funcLuaCommand, TP.C.PARAM_HAS, F.PARAM_TYPE)
      if okB and hasB then
        F.type = funcLuaCommand(TP.C.PARAM_GET, F.PARAM_TYPE) or 0
      end
      pcall(funcLuaCommand, TP.C.PARAM_DEL, TP.KEY_BANK)  -- a request nobody took
      return orig(...)
    end
  end)

  TP.Wrap(STEM, "Step", function(orig)
    return function(...)
      local r = table.pack(orig(...))
      if F.state ~= nil then
        local ok, err = pcall(F.Step)
        if not ok then
          TP.Log("step failed:", tostring(err))
          F.state = nil
          F.grid = nil
          F.Input(true)
        end
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  TP.Wrap(STEM, "OnOpenLayer", function(orig)
    return function(a1, a2, ...)
      if a1 == F.CARD_LAYER and type(a2) == "number" then
        F.built[a2] = F.frame
      end
      if F.eg ~= nil then
        F.eg:Built(a1, a2)
      end
      return orig(a1, a2, ...)
    end
  end)

  TP.Wrap(STEM, "OnEnter", function(orig)
    return function(a1, a2, ...)
      if F.state ~= nil then
        return 1
      end
      if (a1 == TP.CARD or a1 == TP.LEADER) and type(F.set) == "number"
          and not (type(IsChangeMemberMode) == "function" and IsChangeMemberMode())
          and not (type(IsSubMenuBusy) == "function" and IsSubMenuBusy())
          and TP.Local(STEM, "flag2") ~= true
          and TP.M(102308320 --[[CMND_IS_CTRL_FOCUS_ACTIVE?]], a1, a2) == true then
        local h = type(GetFormationSelectCharaStHdl) == "function" and GetFormationSelectCharaStHdl() or nil
        if h == 0 then
          local leader = type(IsSelectLeaderCard) == "function" and IsSelectLeaderCard()
          local slot = leader and TP.LEADER_SLOT or (type(GetFormationSelectCharaIdx) == "function" and GetFormationSelectCharaIdx() or nil)
          if type(slot) == "number" and F.OpenMenu(slot) then
            return 1
          end
        end
      end
      return orig(a1, a2, ...)
    end
  end)

  TP.Wrap(STEM, "UpdateMemberCharaIconInfoByChrStHdl", function(orig)
    return function(...)
      local r = table.pack(orig(...))
      local a = table.pack(...)
      local slot = a[2] or 0
      local layer = a[7] or TP.CARD
      local inst = a[8] or slot
      if layer == TP.CARD and inst == slot and type(F.set) == "number" then
        if r[1] then
          TP.Unghost(slot)
        elseif (a[1] or 0) == 0 then
          pcall(TP.Ghosts, F.set, F.type, slot)
        end
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  TP.Wrap(STEM, "UpdateLeaderChara_CommonPostProcess", function(orig)
    return function(a1, a2, a3, a4, ...)
      local r = table.pack(orig(a1, a2, a3, a4, ...))
      if a1 == TP.LEADER and type(F.set) == "number" then
        if (a4 or 0) == 0 then
          pcall(TP.Ghosts, F.set, F.type, TP.LEADER_SLOT)
        else
          TP.Unghost(TP.LEADER_SLOT)
        end
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  TP.Wrap(STEM, "UpdateMemberCharaBlankSlot", function(orig)
    return function(a1, a2, a3, ...)
      local r = table.pack(orig(a1, a2, a3, ...))
      local slot = a3 and TP.LEADER_SLOT or (a1 or 0)
      if TP.ghost[slot] ~= nil then
        TP.M(TP.C.LAYER_VISIBLE, a3 and TP.BLANK_LEADER or TP.BLANK, a3 and 0 or slot, false)
      end
      return table.unpack(r, 1, r.n)
    end
  end)
end
